def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the uniform divider between two equal-sized panels.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r > 0 and (h-r-1) == r:
            divider = ('h', r)
            break
    if divider is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and c > 0 and (w-c-1) == c:
                divider = ('v', c)
                break
    if divider is None:
        raise ValueError('No centered uniform divider found')
    if divider[0] == 'h':
        k = divider[1]
        first, second = grid[:k], grid[k+1:]
    else:
        k = divider[1]
        first = [row[:k] for row in grid]
        second = [row[k+1:] for row in grid]
    colors1 = {v for row in first for v in row}
    colors2 = {v for row in second for v in row}
    common = colors1 & colors2
    # The shared color is the panel background; mark its aligned overlap.
    bg = next(iter(common))
    return [[3 if a == bg and b == bg else bg for a, b in zip(ra, rb)]
            for ra, rb in zip(first, second)]
